   document.addEventListener('DOMContentLoaded', function() {
    const readMoreBtn = document.querySelector('.read-more-btn');
    const readMoreDiv = document.querySelector('.read-more-div');

    // Check if the elements exist
    if (readMoreBtn && readMoreDiv) {
        readMoreBtn.addEventListener('click', function() {
            // Toggle the show class to animate the div
            readMoreDiv.classList.toggle('show'); 

            // Hide or show the button based on the current state
            if (readMoreDiv.classList.contains('show')) {
                readMoreBtn.style.display = 'none'; // Hide button when content is shown
            } else {
                readMoreBtn.style.display = 'inline-block'; // Show button when content is hidden
            }
        });
    } else {
        console.warn('Elements not found: ', { readMoreBtn, readMoreDiv });
    }
});

document.addEventListener("DOMContentLoaded", function () {
    setTimeout(function () {
        document.querySelectorAll('.elementor-image-carousel a').forEach(function (el) {
            el.setAttribute('data-elementor-open-lightbox', 'yes');
            el.setAttribute('data-elementor-lightbox-slideshow', 'yes');
            el.setAttribute('data-elementor-lightbox-type', 'image');

            el.addEventListener('click', function (event) {
                event.preventDefault(); // Prevents redirection

                // Check if Elementor Lightbox is available
                if (typeof elementorFrontend !== 'undefined' && elementorFrontend.modules.lightbox) {
                    elementorFrontend.modules.lightbox.show({
                        index: [...el.parentElement.children].indexOf(el),
                        items: [...el.parentElement.children].map(item => ({
                            url: item.href,
                            type: 'image'
                        }))
                    });
                }
            });
        });
    }, 500);
});

/* =========================================================
   D1 SLIDER LOADER — version-isolated, init-once
   - Captures Swiper 11 into our own namespace so it can't be
     overwritten by other plugins loading different Swiper versions.
   - Skips re-init on the same DOM element (page-builder safety).
   ========================================================= */
(function() {
    'use strict';

    var SWIPER_CDN = 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.js';

    function loadSwiper11(done) {
        // Already captured? Use it.
        if (window.__d1SwiperV11) {
            done(window.__d1SwiperV11);
            return;
        }
        // Already loading? Queue this call.
        if (window.__d1SwiperV11Pending) {
            window.__d1SwiperV11Pending.push(done);
            return;
        }
        window.__d1SwiperV11Pending = [done];

        var s = document.createElement('script');
        s.src = SWIPER_CDN;
        s.async = false;
        s.onload = function() {
            // Capture the Swiper 11 constructor into our namespace
            // IMMEDIATELY — before any other script can overwrite window.Swiper.
            window.__d1SwiperV11 = window.Swiper;

            var queue = window.__d1SwiperV11Pending || [];
            window.__d1SwiperV11Pending = null;
            queue.forEach(function(cb) { cb(window.__d1SwiperV11); });
        };
        s.onerror = function() {
            console.error('[d1-slider] Swiper 11 failed to load from', SWIPER_CDN);
        };
        document.head.appendChild(s);
    }

    function initAll(Swiper) {
        document.querySelectorAll('.d1-testimonials-slider').forEach(function(container) {
            // Init-once guard — avoid double init if script runs twice
            if (container.dataset.d1Init === '1') return;
            container.dataset.d1Init = '1';

            var swiperEl = container.querySelector('.swiper');
            var nextBtn  = container.querySelector('.swiper-button-next');
            var prevBtn  = container.querySelector('.swiper-button-prev');

            if (!swiperEl) return;

            new Swiper(swiperEl, {
                // Only the non-default options — v11 handles the rest natively
                speed: 500,
                grabCursor: true,
                loop: true,

                // Alternative behavior: uncomment `rewind` and comment out `loop`
                // to animate back to slide 1 on reaching the end instead of looping.
                // rewind: true,

                autoplay: {
                    delay: 6000,
                    disableOnInteraction: false,
                    pauseOnMouseEnter: true
                },

                navigation: {
                    nextEl: nextBtn,
                    prevEl: prevBtn
                }
            });
        });
    }

    function start() { loadSwiper11(initAll); }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', start);
    } else {
        start();
    }
})();

