	jQuery(document).ready(function($){
		$('body').on('click', '.js-booking-popup-button', function(e){
			e.preventDefault();

			Calendly.initPopupWidget({
			 url: 'https://calendly.com/design1st/30min-consultation?hide_gdpr_banner=1&primary_color=ff6600',
			 prefill: {

			 },
			 utm: {}
		   });
		})		

        $('body').on('click', '.js-booking-button, .js-booking-button-new, .js-booking-popup-button-july', function(e){
			e.preventDefault();
            $('.calendly-popup-wrap-july').fadeIn();
        });

        $('.calendly-popup-wrap-july .calendly-popup-close').on('click', function(e){
            e.preventDefault();
            $('body').removeClass('popup-active');
            $('.calendly-popup').fadeOut();


			if($('#gform_page_28_2').css('display') == 'none'){
				$('.single-step').removeClass('active');
				$('[data-step="step1"]').addClass('active');
				$('.calendly-popup-container').removeClass('wider');
			  }else{
				$('#gform_previous_button_28').trigger('click');
				$('.single-step').removeClass('active');
				$('[data-step="step1"]').addClass('active');
			  }
        });

        $(document).mouseup(function (e){

            var container = $(".calendly-popup-container");

            if (!container.is(e.target) && container.has(e.target).length === 0){

              container.parent('.calendly-popup-wrap-july').fadeOut();
              $('body').removeClass('popup-active');

			  if($('#gform_page_28_2').css('display') == 'none'){
				$('.single-step').removeClass('active');
				$('[data-step="step1"]').addClass('active');
				$('.calendly-popup-container').removeClass('wider');
			  }else{
				$('#gform_previous_button_28').trigger('click');
				$('.single-step').removeClass('active');
				$('[data-step="step1"]').addClass('active');
			  }

            }
        });

        // Popup Steps
        //------------------------
        //---- Next Button ------//
        //------------------------
        $('body').on("click",".calendly-popup-wrap-july .single-step .step-btn .next-btn", function(e){
            var curr_st = $(this).parents(".single-step").data("step");

            //--- Validation ---
            if($(this).parents(".single-step").find(".step-items .item.active").length == 0) return;

			if(curr_st == 'step1'){
				var bus_opt_step1 = 0;

				jQuery('.calendly-popup-wrap-july .popup-content .single-step[data-step="step1"] .step-items .item').each(function(index, ele){
					if(jQuery(this).hasClass("active")){
						bus_opt_step1 = index + 1;
					}
				});

				if(bus_opt_step1 == 1 || bus_opt_step1 == 2){
					$(this).parents(".single-step").removeClass("active");
					$(`.calendly-popup .single-step[data-step="step-booking"]`).addClass("active");
					calendly_booking_form();
				}else if(bus_opt_step1 == 3){
					$(".calendly-popup-wrap-july .calendly-popup-container .gform-body .gform_page:first-child .gform_page_footer input.gform_next_button").trigger("click");
				}
			}
        });

        //------------------------
        //----- Each Step ------//
        //------------------------
        $('body').on('click', ".calendly-popup-wrap-july .single-step .step-items .item", function(e){
			var curr_st = $(this).parents(".single-step").data("step");

			$(this).parent().children().removeClass("active");
            $(this).addClass("active");
        });

		function calendly_booking_form(){
			var candlyWidge = $('.calendly-popup-wrap-july .step-calendly-form');

			candlyWidge.empty();
			candlyWidge.closest('.calendly-popup-container').addClass('wider');
			Calendly.initInlineWidget({
			 url: 'https://calendly.com/design1st/30min-consultation?hide_gdpr_banner=1&primary_color=ff6600',
			 parentElement: document.querySelector('.calendly-popup-wrap-july .step-calendly-form'),
			 prefill: {

			 },
			 utm: {}
		   });
		}

	});

	jQuery(document).ready(function($){		
        $('body').on('click', '.js-booking-popup-button-email', function(e){
			e.preventDefault();
            $('.email-question-g-form').fadeIn();
        });

        $('.email-question-g-form .calendly-popup-close').on('click', function(e){
            e.preventDefault();
            $('body').removeClass('popup-active');
            $('.calendly-popup').fadeOut();
        });

        $(document).mouseup(function (e){

            var container = $(".calendly-popup-container");

            if (!container.is(e.target) && container.has(e.target).length === 0){

              container.parent('.email-question-g-form').fadeOut();
              $('body').removeClass('popup-active');

            }
        });

	});
